/*
 * A319023  Let S be the sequence generated by these rules: 1 is in S, and if
 *          k is in S, then A057168(k) and A319021(k) are in S, and duplicates
 *          are deleted as they occur; a(n) is the n-th term of S.
 * https://oeis.org/A319023
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, look
 * Formula:   S built by BFS from 1: process terms in order, appending
 *            A057168(k) then A319021(k) if not already present; a(n) = n-th
 *            term of S
 * Range:     u8 n <= 41, u16 n <= 217, u32 n <= 3323, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 81 terms through n = 8459 (2026-11-08)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>
#include "../utils/mem.h"

static seq_t A057168_a(seq_t x)
{
    if (x == (seq_t)0) return (seq_t)0;
    seq_t c = (seq_t)1;
    while (((x / c) % (seq_t)2) == (seq_t)0) c = c * (seq_t)2;
    seq_t r = x + c;
    return (((r ^ x) >> 2) / c) | r;
}

static seq_t A319021_a(seq_t n)
{
    if (n == (seq_t)0) return (seq_t)0;
    seq_t tmp = n;
    unsigned char digits[4096];
    size_t len = 0;
    while (tmp > (seq_t)0) {
        digits[len++] = (unsigned char)(long long)(tmp % (seq_t)3);
        tmp /= (seq_t)3;
    }
    unsigned int sum = 0;
    for (size_t i = 0; i < len; ++i) sum += digits[i];

    unsigned char res[4100];
    unsigned int prefix = 0;
    for (size_t i = 0; i < len; ++i) {
        if (digits[i] < 2 && prefix >= 1) {
            unsigned int needed = prefix - 1;
            for (size_t j = 0; j < i; ++j) {
                unsigned int val = (needed > 2) ? 2 : needed;
                res[j] = (unsigned char)val;
                needed -= val;
            }
            for (size_t j = i; j < len; ++j)
                res[j] = (j == i) ? (unsigned char)(digits[j] + 1) : digits[j];
            seq_t result = 0;
            for (size_t j = len; j > 0; --j)
                result = result * (seq_t)3 + (seq_t)res[j - 1];
            return result;
        }
        prefix += digits[i];
    }
    size_t res_len = len + 1;
    unsigned int needed = sum - 1;
    for (size_t j = 0; j < res_len - 1; ++j) {
        unsigned int val = (needed > 2) ? 2 : needed;
        res[j] = (unsigned char)val;
        needed -= val;
    }
    res[res_len - 1] = 1;
    seq_t result = 0;
    for (size_t j = res_len; j > 0; --j)
        result = result * (seq_t)3 + (seq_t)res[j - 1];
    return result;
}

#define A319023_HB 1000003u

static seq_t *A319023_T = NULL;
static size_t *A319023_nxt = NULL;
static size_t *A319023_head = NULL;
static size_t A319023_cnt = 0, A319023_cap = 0, A319023_ptr = 0;

static void A319023_add(seq_t x)
{
    size_t h = (size_t)(unsigned long long)(x % (seq_t)A319023_HB);
    for (size_t i = A319023_head[h]; i; i = A319023_nxt[i - 1])
        if (A319023_T[i - 1] == x) return;
    if (A319023_cnt == A319023_cap) {
        size_t ncap = A319023_cap ? A319023_cap * 2 : 1024;
        seq_t *t2 = mem_new(seq_t, ncap);
        for (size_t i = 0; i < A319023_cnt; ++i) t2[i] = A319023_T[i];
        if (A319023_T) mem_free(A319023_T);
        A319023_T = t2;
        A319023_nxt = (size_t *)realloc(A319023_nxt, ncap * sizeof(size_t));
        A319023_cap = ncap;
    }
    A319023_T[A319023_cnt] = x;
    A319023_nxt[A319023_cnt] = A319023_head[h];
    A319023_head[h] = A319023_cnt + 1;
    A319023_cnt++;
}

seq_t a(idx_t n)
{
    if (A319023_head == NULL) {
        A319023_head = (size_t *)calloc(A319023_HB, sizeof(size_t));
        A319023_add((seq_t)1);
    }
    while (A319023_cnt < (size_t)n) {
        seq_t k = A319023_T[A319023_ptr++];
        A319023_add(A057168_a(k));
        A319023_add(A319021_a(k));
    }
    return A319023_T[(size_t)n - 1];
}
